package dev.zomboidmelee.boxing;import dev.zomboidmelee.boxing.CombatChecks18.*;import dev.zomboid.gore.MeleeReaction;
public class MomentumChecks20{public static void main(String[]a){Actor p=new Actor();Zombie z=new Zombie(p.w);z.tickCount=100;var model=new Checks16.Model();MeleeReaction.event(z,(byte)-101);MeleeReaction.pose(model,z,102);float light=Math.abs(model.body.xRot);MeleeReaction.reset(model);if(Math.abs(model.body.xRot)>.0001)throw new AssertionError("pose offsets not restored");MeleeReaction.event(z,(byte)-104);MeleeReaction.pose(model,z,102);if(Math.abs(model.body.xRot)<=light*1.5)throw new AssertionError("heavy impact needs more momentum");float left=model.body.yRot;MeleeReaction.reset(model);MeleeReaction.event(z,(byte)-105);MeleeReaction.pose(model,z,102);if(left*model.body.yRot>=0)throw new AssertionError("hit side must reverse twist");MeleeReaction.reset(model);MeleeReaction.pose(model,z,120);if(Math.abs(model.body.xRot)>.0001)throw new AssertionError("momentum must settle");Combat18.ACTION.set(1);try{MeleeReaction.damage(new ActionChecks20.Damage(z,p,1));}finally{Combat18.ACTION.remove();}if(p.w.lastEvent> -104||p.w.lastEvent< -106)throw new AssertionError("armored heavy still needs heavy reaction cue");System.out.println("DIRECTION_STRENGTH_MOMENTUM_MODEL_RESET_AND_ARMORED_HEAVY_CHECKS=6");}}
